using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows.Forms;
namespace PZ3D {
 sealed partial class MainForm {
  Label shootState;TextBox shootEvidence;string shootBackup;
  void AddShootClientPage(TabControl tabs){var page=Page(tabs,"射击客户端实验");shootState=new Label{AutoSize=true,MaximumSize=new Size(1000,0),Margin=new Padding(8)};page.Controls.Add(shootState);AddText(page,"Shoot to Thrill（原 I SEE THEM）· 作者多人版\n联机使用时，服务器需启用 ShootToThrillMultiplayer，客户端安装枪械组件。\n只启用 ShootToThrillMultiplayer，不混开单人版、旧版、Recoil & ADS 或 True Ballistics。先在首页安装 / 启用 3D 与 Buddy。加入服务器可能重建模组列表；请按服务器规则使用。");
   var actions=new FlowLayoutPanel{AutoSize=true,WrapContents=true,MaximumSize=new Size(1000,0)};actions.Controls.Add(Button("安装 / 启用作者枪械",()=>{if(MessageBox.Show(this,"将从作者工坊下载缺失文件并备份修改本地 default.txt，同时清理本工具已退役的本地瞄准补丁。\n完整多人功能需要服务器与客户端模组匹配；首次需你确认作者 Java 文件授权。是否继续？","作者枪械模组",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)==DialogResult.OK)Run(EnableShootClient,"正在准备作者射击多人版");}));actions.Controls.Add(Button("关闭作者枪械",()=>Run(()=>{var store=new ShootClient();string result=store.Disable(GetEngine());RememberShootBackup(store);return result;})));actions.Controls.Add(Button("检查射击模组更新",()=>Run(()=>{var engine=GetEngine();engine.Guard();var bridge=new PresentationBridge();string cleanup;try{cleanup=bridge.Retire(engine);}finally{RememberPresentationBackup(bridge);}DownloadSelected(new[]{ShootClient.Item});return cleanup+"\r\n已核对射击模组版本；没有自动启用。更新后完全重启游戏并核对 Java 授权。";})));actions.Controls.Add(Button("读取最近射击日志",ReadShootEvidence));page.Controls.Add(actions);
   AddButton(page,"打开备份 / 人工恢复说明",()=>{string pointer=Path.Combine(data,"shoot-backup-path.txt");if(shootBackup==null&&File.Exists(pointer))shootBackup=File.ReadAllText(pointer);if(shootBackup==null||!Directory.Exists(shootBackup))throw new Exception("尚无射击配置操作备份。");Links.Open(shootBackup);});AddButton(page,"作者工坊与说明",()=>Links.Open("https://steamcommunity.com/sharedfiles/filedetails/?id=3813032735"));AddText(page,ReticleHelp+"\n\n射击扩展版权归 haru，前置版权归各原作者。工具保留工坊文件、个人校准及基础 3D。下方可查看最近的枪械模组日志。");shootEvidence=new TextBox{Width=1000,Height=220,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Text="尚未读取日志。"};page.Controls.Add(shootEvidence);Theme(page);UpdateShootState();}
  void RememberShootBackup(ShootClient store){if(store.LastBackup!=null){shootBackup=store.LastBackup;File.WriteAllText(Path.Combine(data,"shoot-backup-path.txt"),shootBackup);}}
  string EnableShootClient(){var engine=GetEngine();engine.Guard();if(!ShootClient.BaseReady(engine))throw new Exception("请先安装基础 3D 与 Buddy。");string source=InstallWorkflow.Source(engine,ShootClient.Item);try{ShootClient.Validate(source);ReportDownload(100,"枪械扩展文件完整，复用本地文件；最新版请点检查更新");}catch{source=DownloadSelected(new[]{ShootClient.Item})[ShootClient.Item];}var store=new ShootClient();string result=store.Enable(engine,source);RememberShootBackup(store);var bridge=new PresentationBridge();try{result+="\r\n"+bridge.Retire(engine);}finally{RememberPresentationBackup(bridge);}return result+"\r\n完整多人功能需要服务器与客户端模组匹配。重启游戏后核对作者按键与实际效果。";}
  void UpdateShootState(){if(shootState==null)return;try{var engine=GetEngine();shootState.Text="作者枪械："+(ShootClient.Enabled(engine)?"已配置":"未安装 / 已卸载")+"　游戏内中文："+(ChinesePatch.Enabled(engine)?"已配置":"未安装 / 已卸载")+"\n使用：O 开第一人称 → 右键瞄准；Ctrl+V 切换腰射/精瞄（以游戏内绑定为准）。中文需游戏语言为简体中文并批准 laoyu.javacn。"+"\n完整多人功能需要服务器与客户端模组匹配。卸载只作用于勾选项。";}catch(Exception e){shootState.Text=e.Message;}}
  void ReadShootEvidence(){string file=Path.Combine(UserDir(),"console.txt");if(!File.Exists(file)){shootEvidence.Text="尚无 console.txt。请启动游戏并进入服务器后再读取。";return;}string text;using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream))text=reader.ReadToEnd();var lines=text.Split('\n').Where(l=>Regex.IsMatch(l,@"(?i)ORANGE-ADS|STT-MP-INPUT|STT-MP-SETTINGS|IST-NET|ISeeThem|ShootToThrill|iseethem|server bridge|native combat|native shot observer|route-unavailable")).ToArray();var selected=lines.Where(l=>!l.Contains("[ORANGE-ADS]")).Reverse().Take(60).Reverse().Concat(lines.Where(l=>l.Contains("[ORANGE-ADS]")).Reverse().Take(40).Reverse());shootEvidence.Text="最近枪械模组日志\r\n"+file+"\r\n修改时间："+File.GetLastWriteTime(file)+"\r\n\r\n"+(selected.Any()?string.Join("\r\n",selected):"未找到枪械日志，请检查模组是否启用及 Java 授权状态。");}
 }
}
